732	/// F507
733	pub(crate) fn percent_format_positional_count_mismatch(
734	    checker: &Checker,
735	    summary: &CFormatSummary,
736	    right: &Expr,
737	    location: TextRange,
738	) {
739	    if !summary.keywords.is_empty() {
740	        return;
741	    }
742	
743	    if let Expr::Tuple(tuple) = right {
744	        let mut found = 0;
745	        for element in tuple {
746	            if element.is_starred_expr() {
747	                return;
748	            }
749	            found += 1;
750	        }
751	
752	        if found != summary.num_positional {
753	            checker.report_diagnostic(
754	                PercentFormatPositionalCountMismatch {
755	                    wanted: summary.num_positional,
756	                    got: found,
757	                },
758	                location,
759	            );
760	        }
761	    } else if let ResolvedPythonType::Atom(resolved_type) = ResolvedPythonType::from(right) {
762	        // If we can infer a concrete non-tuple type for the RHS, it's always
763	        // a single positional argument. Variables, attribute accesses, calls,
764	        // etc. resolve to `Unknown` and are not flagged because they could be
765	        // tuples at runtime.
766	        if resolved_type != PythonType::Tuple && summary.num_positional != 1 {
767	            checker.report_diagnostic(
768	                PercentFormatPositionalCountMismatch {
769	                    wanted: summary.num_positional,
770	                    got: 1,
771	                },
772	                location,
773	            );
774	        }
775	    }
776	}
